// Interactive versions of lessons 6–9. The pure calculations live in learning-math.js.
import {makeLab,el} from './shared.js';
import {clamp,bell,linspace,imageLoss,chain,curveLoss,numericalDerivative,targetImage,initializeSpots,renderAndGradient,sgdStep,exportScene} from '../learning-math.js';
const blue='#3857b8',orange='#c96b39',green='#63824d',ink='#26372f',muted='#627268';
const number=(x,d=6)=>!Number.isFinite(x)?'—':x!==0&&Math.abs(x)<1e-5?x.toExponential(3):String(Number(x.toFixed(d)));
const copy=x=>JSON.parse(JSON.stringify(x));
const safe=(v,lo,hi,fallback)=>Number.isFinite(Number(v))?clamp(Number(v),lo,hi):fallback;
let id=0;

function shell(host,lang,title,subtitle) {
  if(!document.querySelector('[data-learning-style]')){const link=el('link');link.rel='stylesheet';link.href=new URL('./learning.css',import.meta.url).href;link.dataset.learningStyle='';document.head.append(link);}
  const ui=makeLab(host,{lang,title,subtitle});ui.root.classList.add('learning-lab');
  const events=new AbortController(),observers=[];let alive=true,frame=0;
  ui.t=(ru,en)=>lang==='en'?en:ru;
  ui.on=(node,event,fn)=>node.addEventListener(event,fn,{signal:events.signal});
  ui.schedule=fn=>{if(!alive||frame)return;frame=requestAnimationFrame(()=>{frame=0;if(alive)fn();});};
  ui.cancel=()=>{cancelAnimationFrame(frame);frame=0;};
  ui.watch=fn=>{const observer=new ResizeObserver(()=>{if(alive)fn();});observer.observe(ui.view);observers.push(observer);};
  ui.destroy=()=>{alive=false;ui.cancel();events.abort();observers.forEach(o=>o.disconnect());ui.root.remove();};
  ui.alive=()=>alive;
  return ui;
}
function numeric(ui,label,value,min,max,step,change,parent=ui.controls){
  const wrap=el('div','learn-control'),row=el('div','learn-number-row'),caption=el('label','',label),input=el('input'),range=el('input');
  input.type='number';range.type='range';range.id='learning-'+(++id);caption.htmlFor=range.id;
  for(const node of[input,range]){Object.assign(node,{min,max,step,value});node.setAttribute('aria-label',label);}
  const set=v=>{input.value=String(v);range.value=String(v);};
  ui.on(range,'input',()=>{input.value=range.value;change(+range.value);});
  ui.on(input,'input',()=>{const v=input.valueAsNumber;if(Number.isFinite(v)&&v>=min&&v<=max){range.value=String(v);change(v);}});
  const normalize=()=>{const v=safe(input.valueAsNumber,min,max,+range.value);set(v);change(v);};
  ui.on(input,'change',normalize);ui.on(input,'blur',normalize);row.append(caption,input);wrap.append(row,range);parent.append(wrap);
  return {set,input,range,disable:v=>{input.disabled=v;range.disabled=v;}};
}
function select(ui,label,choices,value,change){const wrap=el('label','learn-control',label),input=el('select');input.setAttribute('aria-label',label);for(const[v,text]of choices){const opt=el('option','',text);opt.value=v;input.append(opt);}input.value=value;ui.on(input,'change',()=>change(input.value));wrap.append(input);ui.controls.append(wrap);return input;}
function button(ui,parent,label,fn,primary=false){const b=el('button',primary?'learn-primary':'',label);b.type='button';ui.on(b,'click',fn);parent.append(b);return b;}
function table(parent,caption,rows){parent.replaceChildren();const wrap=el('div','learn-table-wrap'),tbl=el('table','learn-table'),cap=el('caption','',caption);tbl.append(cap);const body=el('tbody');for(const row of rows){const tr=el('tr');row.forEach((text,i)=>{const cell=el(i?'td':'th','',text);if(!i)cell.scope='row';tr.append(cell);});body.append(tr);}tbl.append(body);wrap.append(tbl);parent.append(wrap);}
function stats(parent,items){parent.replaceChildren();for(const[label,value]of items){const item=el('div','learn-stat');item.append(el('small','',label),el('strong','',value));parent.append(item);}}
function canvas(parent,label,w=800,h=340){const c=el('canvas','learn-chart');c.width=w;c.height=h;c.dataset.ratio=String(h/w);c.setAttribute('role','img');c.setAttribute('aria-label',label);parent.append(c);return c;}
function pixelPanel(parent,label){const f=el('figure'),caption=el('figcaption','',label),c=el('canvas','learn-pixels');c.width=256;c.height=256;c.setAttribute('role','img');c.setAttribute('aria-label',label);f.append(caption,c);parent.append(f);return c;}
function pixels(c,data,size,selected=-1){const ctx=c.getContext('2d');ctx.clearRect(0,0,256,256);const unit=256/size;for(let y=0;y<size;y++)for(let x=0;x<size;x++){const i=(y*size+x)*3;ctx.fillStyle=`rgb(${[0,1,2].map(k=>Math.round(255*clamp(data[i+k],0,1))).join(' ')})`;ctx.fillRect(x*unit,y*unit,Math.ceil(unit),Math.ceil(unit));}if(selected>=0){ctx.lineWidth=3;ctx.strokeStyle='#f59e0b';ctx.strokeRect((selected%size)*unit+1,Math.floor(selected/size)*unit+1,unit-2,unit-2);}}
function rgbGray(values){return Float64Array.from(values.flatMap(v=>[v,v,v]));}
function errors(pred,target,mode='absolute'){const result=new Float64Array(pred.length);for(let i=0;i<pred.length;i+=3){const d=(pred[i]-target[i]+pred[i+1]-target[i+1]+pred[i+2]-target[i+2])/3;if(mode==='signed'){const v=Math.min(1,Math.abs(d));result.set(d>=0?[1,1-v,1-v]:[1-v,1-v,1],i);}else{const e=(Math.abs(pred[i]-target[i])+Math.abs(pred[i+1]-target[i+1])+Math.abs(pred[i+2]-target[i+2]))/3;const v=mode==='squared'?((pred[i]-target[i])**2+(pred[i+1]-target[i+1])**2+(pred[i+2]-target[i+2])**2)/3:e;result.set([v,v,v],i);}}return result;}
function chart(c,series,{xmin=-4,xmax=4,ymin=0,ymax=1.05,xlabel='x',ylabel='',points=[],segments=[]}={}){
  const w=Math.max(260,c.clientWidth||500),h=Math.max(180,w*Number(c.dataset.ratio||.425)),dpr=Math.min(2,window.devicePixelRatio||1);
  if(c.width!==Math.round(w*dpr)||c.height!==Math.round(h*dpr)){c.width=Math.round(w*dpr);c.height=Math.round(h*dpr);}
  const ctx=c.getContext('2d');ctx.setTransform(dpr,0,0,dpr,0,0);
  const l=57,r=20,t=28,b=45,X=x=>l+(x-xmin)/(xmax-xmin)*(w-l-r),Y=y=>h-b-(y-ymin)/(ymax-ymin)*(h-t-b);
  ctx.fillStyle='#fbfcfa';ctx.fillRect(0,0,w,h);ctx.font='14px system-ui';ctx.fillStyle=muted;ctx.strokeStyle='#dce4dc';ctx.lineWidth=1;
  for(let i=0;i<=4;i++){const y=ymin+(ymax-ymin)*i/4;ctx.beginPath();ctx.moveTo(l,Y(y));ctx.lineTo(w-r,Y(y));ctx.stroke();ctx.fillText(number(y,3),5,Y(y)+5);const x=xmin+(xmax-xmin)*i/4;ctx.fillText(number(x,2),X(x)-10,h-17);}
  ctx.fillStyle=ink;ctx.fillText(ylabel,l,18);ctx.fillText(xlabel,w-r-30,h-4);
  for(const s of series){ctx.strokeStyle=s.color||blue;ctx.lineWidth=2.5;ctx.setLineDash(s.dashed?[7,5]:[]);ctx.beginPath();s.data.forEach(([x,y],i)=>i?ctx.lineTo(X(x),Y(y)):ctx.moveTo(X(x),Y(y)));ctx.stroke();}ctx.setLineDash([]);
  for(const s of segments){ctx.strokeStyle=s.color||orange;ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(X(s.a[0]),Y(s.a[1]));ctx.lineTo(X(s.b[0]),Y(s.b[1]));ctx.stroke();}
  for(const p of points){ctx.fillStyle=p.color||orange;ctx.beginPath();ctx.arc(X(p.x),Y(p.y),5,0,Math.PI*2);ctx.fill();}
}

export function mountLoss(host,lang='ru',saved={}){
  const t=(r,e)=>lang==='en'?e:r,ui=shell(host,lang,t('Картинка и её ошибка','An image and its error'),t('Три вида одного сравнения: образец, текущее пятно и карта разностей. Оранжевая рамка связывает пиксель с вычислением ниже.','Three views of one comparison: target, current spot, and difference map. The orange frame connects a pixel to the calculation below.'));
  const state={example:saved.example==='tiny'?'tiny':'gaussian',mu:safe(saved.mu,-3,3,-1),sigma:safe(saved.sigma,.3,2.5,1.2),gain:safe(saved.gain,0,1,1),mode:['signed','absolute','squared'].includes(saved.mode)?saved.mode:'squared',index:Number.isInteger(saved.index)?saved.index:16*33+16};
  const views=el('div','learn-images');ui.view.append(views);const a=pixelPanel(views,t('Образец T','Target T')),b=pixelPanel(views,t('Результат P','Prediction P')),c=pixelPanel(views,t('Карта ошибки','Error map'));const summary=el('div','learn-stats');ui.view.append(summary);
  select(ui,t('Пример','Example'),[['gaussian',t('Одно пятно','One spot')],['tiny',t('Четыре пикселя','Four pixels')]],state.example,v=>{state.example=v;state.index=0;update();});
  const mx=numeric(ui,t('Центр μₓ','Center μₓ'),state.mu,-3,3,.05,v=>{state.mu=v;update();});
  const sw=numeric(ui,t('Масштаб σ','Scale σ'),state.sigma,.3,2.5,.05,v=>{state.sigma=v;update();});
  const gn=numeric(ui,t('Яркость','Brightness'),state.gain,0,1,.01,v=>{state.gain=v;update();});
  select(ui,t('Вид разности','Difference view'),[['signed',t('Знак: красный +, синий −','Signed: red +, blue −')],['absolute','|P − T|'],['squared','(P − T)²']],state.mode,v=>{state.mode=v;update();});
  const note=el('p','learn-note',t('У образца μₓ = 1, μᵧ = 0, σ = 1.2. Чёрный на карте квадрата означает совпадение, белый — ошибку 1. Шкала цвета фиксирована.','The target has μₓ = 1, μᵧ = 0, σ = 1.2. Black on the squared-error map means a match; white means an error of 1. The color scale stays fixed.'));ui.footer.append(note);
  let size=33,target,pred;
  for(const cn of[a,b,c])ui.on(cn,'click',e=>{const rect=cn.getBoundingClientRect(),x=clamp(Math.floor((e.clientX-rect.left)/rect.width*size),0,size-1),y=clamp(Math.floor((e.clientY-rect.top)/rect.height*size),0,size-1);state.index=y*size+x;update();});
  const probe=numeric(ui,t('Номер пикселя · от 0','Pixel index · from 0'),state.index,0,1088,1,v=>{state.index=Math.round(v);update();});
  function update(){const tiny=state.example==='tiny';mx.disable(tiny);sw.disable(tiny);gn.disable(tiny);size=tiny?2:33;state.index=clamp(state.index,0,size*size-1);probe.input.max=probe.range.max=String(size*size-1);probe.set(state.index);
    if(tiny){target=rgbGray([0,1,.5,.5]);pred=rgbGray([.2,.8,.1,.9]);}else{const tv=[],pv=[];for(let y=0;y<size;y++)for(let x=0;x<size;x++){const xx=-4+8*x/(size-1),yy=4-8*y/(size-1);tv.push(bell(xx,1,1.2)*bell(yy,0,1.2));pv.push(state.gain*bell(xx,state.mu,state.sigma)*bell(yy,0,state.sigma));}target=rgbGray(tv);pred=rgbGray(pv);}
    pixels(a,target,size,state.index);pixels(b,pred,size,state.index);pixels(c,errors(pred,target,state.mode),size,state.index);const loss=imageLoss(pred,target);stats(summary,[[t('Средняя разность','Mean residual'),Math.abs(loss.signed)<1e-12?'≈ 0':number(loss.signed)],['MAE',number(loss.mae)],['MSE',number(loss.mse)]]);
    const p=pred[state.index*3],q=target[state.index*3],d=p-q;table(ui.readout,t('Один пиксель и вся картинка','One pixel and the whole image'),[[t('Пиксель (строка, столбец)','Pixel (row, column)'),`(${Math.floor(state.index/size)}, ${state.index%size})`],['P − T',`${number(p)} − ${number(q)} = ${number(d)}`],['|P − T|',number(Math.abs(d))],['(P − T)²',`${number(d)} × ${number(d)} = ${number(d*d)}`],['MSE',`${number(loss.mse*size*size)} / ${size*size} = ${number(loss.mse)}`],[t('Серое изображение','Grayscale image'),t('Три одинаковых канала дают ту же среднюю ошибку. В знаменателе 3 × число пикселей.','Three identical channels give the same mean error. The denominator is 3 × the pixel count.')]]);
    c.setAttribute('aria-label',t(`Карта ошибки. MSE ${number(loss.mse)}, MAE ${number(loss.mae)}`,`Error map. MSE ${number(loss.mse)}, MAE ${number(loss.mae)}`));
  }update();return {getState:()=>copy(state),destroy:ui.destroy};
}

export function mountDescent(host,lang='ru',saved={}){
  const t=(r,e)=>lang==='en'?e:r,ui=shell(host,lang,t('Наклон и следующий шаг','The slope and the next step'),t('Синий — образец, оранжевый — текущее пятно. Внизу та же настройка показана точкой на графике ошибки.','Blue is the target; orange is the current spot. Below, the same setting appears as a point on the loss curve.'));
  const state={mu:safe(saved.mu,-6,6,-1),eta:safe(saved.eta,.01,12,2),h:safe(saved.h,.0001,1,.01),objective:saved.objective==='quadratic'?'quadratic':'gaussian',steps:Math.round(safe(saved.steps,0,100000,0))};let running=false,last=null;
  const bellCanvas=canvas(ui.view,t('Образец и текущее пятно','Target and current spot')),lossCanvas=canvas(ui.view,t('Ошибка от положения центра','Loss against the center position'));const status=el('p','learn-status');status.setAttribute('role','status');
  const objective=select(ui,t('Ошибка','Loss'),[['gaussian',t('Пятно → образец μ = 1','Spot → target μ = 1')],['quadratic','L(θ) = (θ − 3)²']],state.objective,v=>{pause();state.objective=v;state.mu=v==='quadratic'?1:-1;state.eta=v==='quadratic'?.25:2;mu.set(state.mu);eta.set(state.eta);state.steps=0;last=null;update();});
  const mu=numeric(ui,t('Параметр θ / μ','Parameter θ / μ'),state.mu,-6,6,.01,v=>{pause();state.mu=v;state.steps=0;last=null;update();});
  const eta=numeric(ui,t('Размер шага η','Learning rate η'),state.eta,.01,12,.01,v=>{state.eta=v;update();});
  numeric(ui,t('Приращение h','Difference step h'),state.h,.0001,1,.0001,v=>{state.h=v;update();});
  const actions=el('div','learn-actions');ui.controls.append(actions);button(ui,actions,t('Один шаг','One step'),()=>step());const play=button(ui,actions,t('Обучение','Train'),()=>{running=!running;play.textContent=running?t('Пауза','Pause'):t('Обучение','Train');if(running)tick();},true);button(ui,actions,t('Сброс','Reset'),()=>{pause();state.mu=state.objective==='quadratic'?1:-1;state.steps=0;mu.set(state.mu);last=null;update();});ui.controls.append(status);
  ui.footer.append(el('p','learn-note',t('Ошибка пятна — среднее 81 квадрата разности на x от −4 до 4. Наклон считается по двум соседним значениям ошибки: [L(θ + h) − L(θ − h)] / (2h). Оранжевый отрезок показывает этот наклон. Шаг за границу отображаемой шкалы останавливает опыт.','The spot loss averages 81 squared differences at x from −4 to 4. The slope uses two neighboring losses: [L(θ + h) − L(θ − h)] / (2h). The orange segment shows that slope. A step beyond the displayed range stops the experiment.')));
  const value=x=>state.objective==='quadratic'?(x-3)**2:curveLoss(x,1).loss;
  function pause(){running=false;ui.cancel();play.textContent=t('Обучение','Train');}
  function step(){const before=state.mu,loss=value(before),g=numericalDerivative(value,before,state.h),after=before-state.eta*g;last={before,loss,g,after,newLoss:value(after)};if(!Number.isFinite(after)||Math.abs(after)>6){pause();status.textContent=t(`Следующий параметр ${number(after)} вне шкалы [−6, 6]. При таком η шаг слишком велик.`,`The next parameter ${number(after)} lies outside [−6, 6]. This η makes the step too large.`);status.dataset.error='true';update(false);return false;}state.mu=after;state.steps++;mu.set(after);update();return true;}
  let then=0;function tick(){if(!running||!ui.alive())return;ui.schedule(()=>{if(performance.now()-then>160){then=performance.now();if(!step())return;}tick();});}
  function update(clear=true){const xs=linspace(-6,6,180),g=numericalDerivative(value,state.mu,state.h),L=value(state.mu),quadratic=state.objective==='quadratic';bellCanvas.hidden=quadratic;
    if(!quadratic)chart(bellCanvas,[{color:blue,data:xs.map(x=>[x,bell(x,1)])},{color:orange,data:xs.map(x=>[x,bell(x,state.mu)])}],{xmin:-6,xmax:6,ylabel:t('Вес','Weight')});
    chart(lossCanvas,[{data:xs.map(x=>[x,value(x)])}],{xmin:-6,xmax:6,ymax:quadratic?84:.42,ylabel:'L',xlabel:quadratic?'θ':'μ',points:[{x:state.mu,y:L}],segments:[{a:[state.mu-.7,L-g*.7],b:[state.mu+.7,L+g*.7]}]});
    table(ui.readout,t('От наклона к обновлению','From the slope to the update'),[[t('Текущий параметр','Current parameter'),number(state.mu)],[`L(θ − h), L(θ + h)`,`${number(value(state.mu-state.h))}, ${number(value(state.mu+state.h))}`],[t('Наклон g','Slope g'),number(g)],['θ − ηg',`${number(state.mu)} − ${number(state.eta)} × (${number(g)}) = ${number(state.mu-state.eta*g)}`],...(last?[[t('Последний шаг','Last step'),`${number(last.before)} → ${number(last.after)}`],[t('Ошибка до → после','Loss before → after'),`${number(last.loss)} → ${number(last.newLoss)}`]]:[])]);
    if(clear){status.dataset.error='false';status.textContent=t(`Шагов: ${state.steps}. Текущая ошибка: ${number(L)}.`,`Steps: ${state.steps}. Current loss: ${number(L)}.`);}lossCanvas.setAttribute('aria-label',`L=${number(L)}; θ=${number(state.mu)}; g=${number(g)}`);
  }update();ui.watch(update);return {getState:()=>copy(state),destroy(){pause();ui.destroy();}};
}

export function mountAutograd(host,lang='ru',saved={}){
  const t=(r,e)=>lang==='en'?e:r,ui=shell(host,lang,t('Прямой проход, обратный проход','Forward pass, backward pass'),t('Верхняя строка каждого узла — результат операции. Нижняя — производная общей ошибки по выходу этого узла.','The upper line of each node is its forward value. The lower line is the total loss derivative with respect to that node’s output.'));
  const state={mu:safe(saved.mu,-3,3,0),x:safe(saved.x,-3,3,1),sigma:safe(saved.sigma,.3,2,1),target:safe(saved.target,0,1,.8),initial:safe(saved.initial,-3,3,-1),fitMu:safe(saved.fitMu,-4,4,-1),eta:safe(saved.eta,0,20,2),steps:Math.round(safe(saved.steps,0,100000,0))};let running=false,losses=[];
  const graph=el('div','learn-graph');ui.view.append(graph);const plot=canvas(ui.view,t('Обучение центра гауссианы','Learning a Gaussian center'));const summary=el('div','learn-stats');ui.view.append(summary);
  ui.controls.append(el('h4','learn-group-title',t('Одна точка · цепочка','One point · chain')));
  numeric(ui,t('Центр μ в цепочке','Chain center μ'),state.mu,-3,3,.01,v=>{state.mu=v;update();});numeric(ui,t('Точка x','Point x'),state.x,-3,3,.05,v=>{state.x=v;update();});numeric(ui,t('Масштаб σ','Scale σ'),state.sigma,.3,2,.05,v=>{state.sigma=v;update();});numeric(ui,t('Целевой вес y','Target weight y'),state.target,0,1,.01,v=>{state.target=v;update();});
  ui.controls.append(el('h4','learn-group-title',t('Вся кривая · обучение','Whole curve · training')));
  numeric(ui,t('Начальный центр обучения','Initial training center'),state.initial,-3,3,.1,v=>{pause();state.initial=v;state.fitMu=v;state.steps=0;losses=[];update();});
  const eta=numeric(ui,t('Шаг обучения η','Training rate η'),state.eta,0,20,.01,v=>{state.eta=v;update();});const actions=el('div','learn-actions');ui.controls.append(actions);button(ui,actions,t('Один шаг обучения','One training step'),step);const play=button(ui,actions,t('Обучение','Train'),()=>{running=!running;play.textContent=running?t('Пауза','Pause'):t('Обучение','Train');if(running)tick();},true);button(ui,actions,t('Сброс обучения','Reset training'),()=>{pause();state.fitMu=state.initial;state.steps=0;losses=[];update();});
  const status=el('p','learn-status');status.setAttribute('role','status');ui.controls.append(status);
  ui.footer.append(el('p','learn-note',t('В цепочке выше одна точка и один квадрат ошибки. График ниже обучает центр по средней ошибке 41 точки: образец μ = 1.5, σ = 1; начальный центр задаётся отдельно. Производные складываются и делятся на 41. Здесь вычисления выполняет JavaScript; тот же проход в Python ниже использует PyTorch.','The chain above has one point and one squared error. The plot below fits the center using the mean error over 41 points: target μ = 1.5, σ = 1; the initial center has a separate control. Their derivatives are summed and divided by 41. JavaScript performs the browser calculations; the Python version below uses PyTorch.')));
  function pause(){running=false;ui.cancel();play.textContent=t('Обучение','Train');}
  function step(){const before=curveLoss(state.fitMu,1.5,1,41),candidate=state.fitMu-state.eta*before.gradient;if(Math.abs(candidate)>4||!Number.isFinite(candidate)){pause();status.textContent=t('Шаг вышел за область [−4, 4].','The step left the interval [−4, 4].');return;}state.fitMu=candidate;state.steps++;losses.push(curveLoss(candidate,1.5,1,41).loss);update();}
  let then=0;function tick(){if(!running||!ui.alive())return;ui.schedule(()=>{if(performance.now()-then>90){then=performance.now();step();if(state.steps>=200)pause();}tick();});}
  function update(){const c=chain(state.mu,state.x,state.sigma,state.target),finite=numericalDerivative(m=>chain(m,state.x,state.sigma,state.target).loss,state.mu,1e-5);graph.replaceChildren();
    for(const[label,key,back]of[['d = x − μ','d','d'],['u = d / σ','u','u'],['q = u × u','q','q'],['t = −q / 2','t','t'],['G = exp(t)','weight','weight'],['r = G − y','residual','residual']]){const node=el('div','learn-node');node.append(el('small','',label),el('strong','',number(c[key])),el('em','',`∂L/∂${label.split(' ')[0]} = ${number(c.backwards[back])}`));graph.append(node);}
    const xs=linspace(-4,4,101);chart(plot,[{color:blue,data:xs.map(x=>[x,bell(x,1.5)])},{color:orange,data:xs.map(x=>[x,bell(x,state.fitMu)])}],{ylabel:t('Вес','Weight')});const fit=curveLoss(state.fitMu,1.5,1,41);stats(summary,[[t('Шаг','Step'),state.steps],[t('Центр модели','Model center'),number(state.fitMu)],['MSE (41)',number(fit.loss)]]);
    table(ui.readout,t('Производная одной цепочки','Derivative of one chain'),[['L = r²',number(c.loss)],['∂L/∂μ',`2r × G × (−1/2) × 2u × (1/σ) × (−1) = ${number(c.gradient)}`],[t('Проверка с h = 0.00001','Check with h = 0.00001'),`[L(μ+h) − L(μ−h)] / (2h) = ${number(finite)}`],[t('Разность двух способов','Difference between methods'),number(Math.abs(c.gradient-finite),12)]]);status.textContent=t(`Для графика: g = ${number(fit.gradient)}; следующий центр = ${number(state.fitMu-state.eta*fit.gradient)}.`,`For the plot: g = ${number(fit.gradient)}; next center = ${number(state.fitMu-state.eta*fit.gradient)}.`);
  }update();ui.watch(update);return{getState:()=>copy(state),destroy(){pause();ui.destroy();}};
}

export function mountFitting(host,lang='ru',saved={}){
  const t=(r,e)=>lang==='en'?e:r,ui=shell(host,lang,t('Из пятен — к образцу','From spots toward a target'),t('Каждый кадр справа получается из текущих параметров. Один шаг считает производные всей картинки и обновляет центры, размеры, RGB и непрозрачность.','Every frame on the right is rendered from the current parameters. One step differentiates the whole image, then updates centers, scales, RGB, and opacity.'));
  const size=32,state={kind:['shapes','checker','flower','sunset'].includes(saved.kind)?saved.kind:'shapes',count:[16,32,64,128].includes(saved.count)?saved.count:64,seed:Math.round(safe(saved.seed,1,9999,42)),mode:['grid','random','center'].includes(saved.mode)?saved.mode:'grid',scale:safe(saved.scale,.2,3,.55),rate:safe(saved.rate,0,20,4),steps:0};
  let target=targetImage(state.kind,size),params,output,history=[],running=false,uploadVersion=0,custom=false;
  const panels=el('div','learn-images');ui.view.append(panels);const goal=pixelPanel(panels,t('Образец · 32 × 32','Target · 32 × 32')),prediction=pixelPanel(panels,t('Текущие гауссианы','Current Gaussians')),difference=pixelPanel(panels,t('Средняя |ошибка RGB|','Mean |RGB error|'));const summary=el('div','learn-stats');ui.view.append(summary);const curve=canvas(ui.view,t('История ошибки','Loss history'),800,300);
  const targetChoice=select(ui,t('Картинка','Image'),[['shapes',t('Круг, прямоугольник и полоса','Circle, rectangle, stripe')],['checker',t('Мелкие клетки','Small checks')],['flower',t('Цветок','Flower')],['sunset',t('Закат','Sunset')]],state.kind,v=>{uploadVersion++;state.kind=v;custom=false;target=targetImage(v,size);reset();});
  select(ui,t('Количество пятен','Spot count'),[16,32,64,128].map(n=>[String(n),String(n)]),String(state.count),v=>{state.count=+v;reset();});
  select(ui,t('Начальные центры','Initial centers'),[['grid',t('Сетка','Grid')],['random',t('Случайно','Random')],['center',t('Около центра','Near center')]],state.mode,v=>{state.mode=v;reset();});
  numeric(ui,t('Начальный масштаб','Initial scale'),state.scale,.2,3,.05,v=>{state.scale=v;reset();});numeric(ui,t('Seed','Seed'),state.seed,1,9999,1,v=>{state.seed=Math.round(v);reset();});numeric(ui,t('Шаг η','Learning rate η'),state.rate,0,20,.05,v=>{state.rate=v;});
  const actions=el('div','learn-actions');ui.controls.append(actions);const stepButton=button(ui,actions,t('Один шаг','One step'),()=>advance(1)),ten=button(ui,actions,t('10 шагов','10 steps'),()=>advance(10)),play=button(ui,actions,t('Обучение','Train'),()=>{running=!running;sync();if(running)tick();},true);button(ui,actions,t('Заново','Restart'),reset);
  const fileLabel=el('label','learn-file',t('Своя картинка · белые поля','Local image · white padding')),file=el('input');file.type='file';file.accept='image/png,image/jpeg,image/webp';file.setAttribute('aria-label',t('Своя картинка','Local image'));fileLabel.append(file);ui.controls.append(fileLabel);
  const download=button(ui,ui.controls,t('Скачать сцену JSON','Download scene JSON'),()=>{const text=JSON.stringify(exportScene(params),null,2),url=URL.createObjectURL(new Blob([text],{type:'application/json'})),a=el('a');a.href=url;a.download='trained-gaussian-scene.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);});
  const status=el('p','learn-status');status.setAttribute('role','status');ui.controls.append(status);
  ui.footer.append(el('p','learn-note',t('Образец содержит 32 × 32 × 3 числа. Обучаются восемь параметров каждого пятна; угол остаётся нулевым, порядок слоёв и белый фон фиксированы. После шага значения ограничиваются: центры [−4, 4], масштабы [0.2, 3], RGB и непрозрачность [0, 1]. Каждый запуск останавливается после 500 шагов; продолжение сохраняет параметры.','The target contains 32 × 32 × 3 numbers. Eight parameters per spot are learned; angles stay zero, layer order and the white background stay fixed. Each update is projected into bounds: centers [−4, 4], scales [0.2, 3], RGB and opacity [0, 1]. Each run stops after 500 steps; resuming keeps the parameters.')));
  let stopAt=500;
  function sync(){play.textContent=running?t('Пауза','Pause'):t('Обучение','Train');stepButton.disabled=ten.disabled=running;}
  function pause(){running=false;ui.cancel();sync();}
  function reset(){pause();params=initializeSpots(target,size,state.count,state.seed,state.mode,state.scale);state.steps=0;output=renderAndGradient(params,target,size);history=[[0,output.loss]];status.dataset.error='false';draw();}
  function advance(n){if(n>1){running=true;stopAt=state.steps+n;sync();tick();return;}advanceRaw();draw();}
  function tick(){if(!running||!ui.alive())return;if(state.steps>=stopAt)stopAt=state.steps+500;const limit=stopAt;const iterate=()=>{if(!running||!ui.alive())return;ui.schedule(()=>{const start=performance.now();do{advanceRaw();}while(performance.now()-start<18&&state.steps<limit);draw();if(state.steps>=limit)pause();else iterate();});};iterate();}
  function advanceRaw(){params=sgdStep(params,output.gradient,state.rate);output=renderAndGradient(params,target,size);state.steps++;history.push([state.steps,output.loss]);}
  function draw(){pixels(goal,target,size);pixels(prediction,output.image,size);pixels(difference,errors(output.image,target),size);stats(summary,[[t('Шаг','Step'),state.steps],[t('Параметров','Parameters'),state.count*8],['MSE',number(output.loss)]]);const ymax=Math.max(.0001,...history.map(x=>x[1]))*1.1;chart(curve,[{data:history,color:blue}],{xmin:0,xmax:Math.max(10,state.steps),ymax,ylabel:'MSE',xlabel:t('шаг','step')});status.textContent=t(`Ошибка: ${number(history[0][1])} → ${number(output.loss)}.`,`Loss: ${number(history[0][1])} → ${number(output.loss)}.`);prediction.setAttribute('aria-label',t(`Восстановленная картинка. Шаг ${state.steps}, MSE ${number(output.loss)}.`,`Reconstructed image. Step ${state.steps}, MSE ${number(output.loss)}.`));table(ui.readout,t('Один шаг в числах','One step in numbers'),[[t('Число сравниваемых значений','Compared values'),'32 × 32 × 3 = 3072'],[t('Правило обновления','Update rule'),`θ ← θ − ${number(state.rate)} × ∂MSE/∂θ`],[t('Первое пятно: центр','First spot: center'),`(${number(params[0])}, ${number(params[1])})`],[t('Его масштабы σₓ, σᵧ','Its scales σₓ, σᵧ'),`(${number(params[2])}, ${number(params[3])})`],[t('Его непрозрачность','Its opacity'),number(params[4])],[t('Текущий ∂MSE/∂μₓ','Current ∂MSE/∂μₓ'),number(output.gradient[0])]]);}
  ui.on(file,'change',async()=>{const selected=file.files?.[0];if(!selected)return;const version=++uploadVersion;if(selected.size>10*1024*1024){status.textContent=t('Размер файла больше 10 МБ.','The file exceeds 10 MB.');status.dataset.error='true';return;}pause();try{const bitmap=await createImageBitmap(selected);if(!ui.alive()||version!==uploadVersion){bitmap.close();return;}const c=document.createElement('canvas');c.width=c.height=size;const ctx=c.getContext('2d'),ratio=Math.min(size/bitmap.width,size/bitmap.height),width=Math.max(1,Math.round(bitmap.width*ratio)),height=Math.max(1,Math.round(bitmap.height*ratio));ctx.fillStyle='white';ctx.fillRect(0,0,size,size);ctx.drawImage(bitmap,Math.floor((size-width)/2),Math.floor((size-height)/2),width,height);bitmap.close();const rgba=ctx.getImageData(0,0,size,size).data;target=Float64Array.from({length:size*size*3},(_,i)=>rgba[Math.floor(i/3)*4+i%3]/255);custom=true;targetChoice.selectedIndex=-1;reset();status.textContent=t(`Картинка «${selected.name}»: пропорции сохранены, свободное место заполнено белым; 32 × 32.`,`Image “${selected.name}”: aspect ratio preserved with white padding; 32 × 32.`);}catch{status.textContent=t('Файл не удалось прочитать как картинку.','The file could not be read as an image.');status.dataset.error='true';}});
  let restored=false;
  if(Array.isArray(saved.parameters)&&saved.parameters.length===state.count*8){try{if(Array.isArray(saved.target)&&saved.target.length===size*size*3&&saved.target.every(v=>Number.isFinite(v)&&v>=0&&v<=1)){target=Float64Array.from(saved.target);custom=!!saved.custom;}params=Float64Array.from(saved.parameters);output=renderAndGradient(params,target,size);state.steps=Math.floor(safe(saved.steps,0,1000000,0));history=Array.isArray(saved.history)&&saved.history.length&&saved.history.every(row=>Array.isArray(row)&&row.length===2&&row.every(Number.isFinite))?copy(saved.history):[[state.steps,output.loss]];restored=true;if(custom)targetChoice.selectedIndex=-1;draw();}catch{restored=false;}}
  if(!restored)reset();ui.watch(draw);return {getState:()=>({...copy(state),parameters:Array.from(params),target:Array.from(target),custom,history:copy(history)}),destroy(){uploadVersion++;pause();ui.destroy();}};
}
